  if (n.type === 'COMPONENT' || n.type === 'COMPONENT_SET') o.key = n.key;
  if (n.fills && n.fills.length) o.fills = n.fills;
  if (n.strokes && n.strokes.length) o.strokes = n.strokes;
  if (n.cornerRadius !== undefined && n.cornerRadius !== figma.mixed) o.radius = n.cornerRadius;
  if (n.effects && n.effects.length) o.effects = n.effects;
  if (n.type === 'TEXT') { o.font = n.fontName; o.size = n.fontSize; o.chars = n.characters; o.color = n.fills; o.align = n.textAlignHorizontal; }
  if ('children' in n) o.children = n.children.map(c => dump(c, d + 1));
