const page=await figma.getNodeByIdAsync('8:2');await figma.setCurrentPageAsync(page);
await figma.loadFontAsync({family:'Roboto',style:'Regular'});
await figma.loadFontAsync({family:'Roboto',style:'Medium'});
const s7=await figma.getNodeByIdAsync('20:300');
// shift everything between header (100) and tab bar (756) down by 30 to open a search row
const movable=s7.children.filter(c=>{
  const y=c.y, name=c.name;
  if(['Status Bar','Home Indicator','AppHeader / Trade Home','Trade Tab Bar'].includes(name))return false;
  return y>=104;
});
movable.forEach(c=>{c.y=c.y+30;});
// search pill
const solid=(h,a)=>{h=h.replace('#','');const c={r:parseInt(h.slice(0,2),16)/255,g:parseInt(h.slice(2,4),16)/255,b:parseInt(h.slice(4,6),16)/255};return a!==undefined?{type:'SOLID',color:c,opacity:a}:{type:'SOLID',color:c};};
const pill=figma.createFrame();s7.appendChild(pill);pill.name='Search';pill.resize(350,32);pill.x=20;pill.y=104;pill.cornerRadius=10;pill.fills=[solid('#141A23')];
const ic=(await figma.getNodeByIdAsync('10:37')).createInstance();pill.appendChild(ic);ic.resize(16,16);ic.x=10;ic.y=8;
ic.findAll(()=>true).forEach(n=>{if(Array.isArray(n.fills)&&n.fills.length&&n.fills.some(f=>f.type==='SOLID')){try{n.fills=[solid('#8C96A8')];}catch(e){}}});
const st=figma.createText();pill.appendChild(st);st.fontName={family:'Roboto',style:'Regular'};st.fontSize=11;st.characters='Search';st.fills=[solid('#8C96A8')];st.x=34;st.y=8;
return {moved:movable.length,search:{y:pill.y,h:pill.height},bottom:s7.children.filter(c=>c.name==='rates').map(c=>Math.round(c.y))};

const page=await figma.getNodeByIdAsync('8:2');await figma.setCurrentPageAsync(page);
const lib=await figma.getNodeByIdAsync('15:2');
// grid: headers left column (x=600), business components right column (x=1010)
const headers=lib.children.filter(c=>c.type==='COMPONENT'&&c.name.startsWith('AppHeader / '));
headers.forEach((c,i)=>{c.x=600;c.y=96+i*76;});
const biz=lib.children.filter(c=>c.type==='COMPONENT'&&!c.name.startsWith('AppHeader / '));
biz.forEach((c,i)=>{c.x=1010;c.y=96+i*180;});
const maxY=Math.max(...lib.children.map(c=>c.y+c.height));
lib.resize(Math.max(1400,1200),Math.max(1900,maxY+60));
return {headers:headers.map(h=>({n:h.name,y:Math.round(h.y)})),biz:biz.map(b=>({n:b.name,y:Math.round(b.y)})),libH:Math.round(lib.height)};

const page=await figma.getNodeByIdAsync('8:2');await figma.setCurrentPageAsync(page);
const names=['01_Welcome','02_Photo_ID','03_Bank_Home','04_Bank_Transactions','05_Profile','06_XTrade_Welcome','07_Trade_Home','08_Market','09_Exchange_Stock','10_Exchange_Crypto'];
const out={};
for(const n of names){
  const f=page.children.find(c=>c.name===n);
  const tab=f.children.find(c=>c.type==='INSTANCE'&&/Tab Bar/.test(c.name));
  const active=tab?tab.findAll(x=>x.type==='TEXT').filter(x=>x.fills&&x.fills[0]&&x.fills[0].color&&x.fills[0].color.b>0.9).map(x=>x.characters).slice(0,1):null;
  const unread=f.findAll(x=>x.type==='RECTANGLE'&&Math.round(x.width)===8&&Math.round(x.height)===8).length;
  out[n]={tab:tab?tab.name.split('/').pop():'none',unread,links:f.findAll(x=>x.reactions&&x.reactions.length).length};
}
// selected day + amount state
const s4=page.children.find(c=>c.name==='04_Bank_Transactions');
out.day=s4.findAll(x=>x.type==='TEXT'&&x.characters.startsWith('Thu 04')).map(x=>x.characters);
const s9=page.children.find(c=>c.name==='09_Exchange_Stock');
out.amount=s9.findAll(x=>x.type==='TEXT'&&x.characters==='$156.50').length;
const s7=page.children.find(c=>c.name==='07_Trade_Home');
const rates=s7.findOne(c=>c.name==='rates');
out.ratesKids=rates?rates.children.filter(c=>c.type==='TEXT').map(c=>({ch:c.characters.slice(0,12),x:Math.round(c.x),y:Math.round(c.y),w:Math.round(c.width),al:c.textAlignHorizontal})):null;
return out;

const page=await figma.getNodeByIdAsync('8:2');await figma.setCurrentPageAsync(page);
const names=['01_Welcome','02_Photo_ID','03_Bank_Home','04_Bank_Transactions','05_Profile','06_XTrade_Welcome','07_Trade_Home','08_Market','09_Exchange_Stock','10_Exchange_Crypto'];
const frames=names.map(n=>{const f=page.children.find(c=>c.name===n);return f?{n,id:f.id,w:Math.round(f.width),h:Math.round(f.height),links:f.findAll(x=>x.reactions&&x.reactions.length).length}:{n,missing:true};});
const lib=page.children.find(c=>c.name==='01 · Components Library');
const comps=lib?lib.findAll(c=>c.type==='COMPONENT').length:0;
const sets=lib?lib.findAll(c=>c.type==='COMPONENT_SET').length:0;
const shelf=page.children.find(c=>c.name==='00 · Assets (component masters)');
const totalLinks=frames.reduce((a,f)=>a+(f.links||0),0);
const instances=names.reduce((a,n)=>{const f=page.children.find(c=>c.name===n);return a+(f?f.findAll(c=>c.type==='INSTANCE').length:0);},0);
return {pageId:page.id,frames,comps,componentSets:sets,masters:shelf?shelf.children.length:0,totalLinks,instancesInScreens:instances};
